INSERT INTO "ProcessStep" ("slug", "position", "image", "title", "duration", "keywords", "tagline", "text", "items", "team", "updatedAt") VALUES
('strategy', 0, '/images/projects/Mont-k.webp', '{"en": "Strategy", "fr": "Stratégie", "es": "Estrategia", "de": "Strategie"}'::jsonb, '{"en": "1–2 weeks", "fr": "1 à 2 semaines", "es": "1 a 2 semanas", "de": "1–2 Wochen"}'::jsonb, '{"en": "Workshops, audit, roadmap", "fr": "Ateliers, audit, roadmap", "es": "Talleres, auditoría, roadmap", "de": "Workshops, Audit, Roadmap"}'::jsonb, '{"en": "Know where you are going before a single pixel is drawn.", "fr": "Savoir où aller avant de dessiner le moindre pixel.", "es": "Saber adónde ir antes de dibujar un solo píxel.", "de": "Wissen, wohin es geht, bevor der erste Pixel entsteht."}'::jsonb, '{"en": "We sit down with you, your team and your clients to understand what makes your project worth building, then turn it into *a clear plan*.", "fr": "Nous échangeons avec vous, votre équipe et vos clients pour comprendre ce qui rend votre projet unique, puis nous le traduisons en *un plan clair*.", "es": "Hablamos contigo, con tu equipo y con tus clientes para entender qué hace único tu proyecto, y lo convertimos en *un plan claro*.", "de": "Wir sprechen mit Ihnen, Ihrem Team und Ihren Kunden, um zu verstehen, was Ihr Projekt besonders macht, und machen daraus *einen klaren Plan*."}'::jsonb, '{"en": ["Discovery workshops with your team", "Audit of your brand, website and tools", "Positioning and key messages", "Product scoping and feature priorities", "Roadmap, budget and planning", "Market and trend watch"], "fr": ["Ateliers de découverte avec votre équipe", "Audit de votre marque, de votre site et de vos outils", "Positionnement et messages clés", "Cadrage produit et priorisation des fonctionnalités", "Feuille de route, budget et planning", "Veille marché et tendances"], "es": ["Talleres de descubrimiento con tu equipo", "Auditoría de tu marca, tu web y tus herramientas", "Posicionamiento y mensajes clave", "Definición del producto y prioridades de funciones", "Hoja de ruta, presupuesto y planificación", "Vigilancia de mercado y tendencias"], "de": ["Discovery-Workshops mit Ihrem Team", "Audit von Marke, Website und Tools", "Positionierung und Kernbotschaften", "Produktumfang und Priorisierung der Funktionen", "Roadmap, Budget und Zeitplan", "Markt- und Trendbeobachtung"]}'::jsonb, ARRAY['camille', 'fanga', 'mazouz', 'noah']::text[], CURRENT_TIMESTAMP),
('brand', 1, '/images/projects/Marcel%202x3%20rebranding.png', '{"en": "Brand", "fr": "Marque", "es": "Marca", "de": "Marke"}'::jsonb, '{"en": "2–4 weeks", "fr": "2 à 4 semaines", "es": "2 a 4 semanas", "de": "2–4 Wochen"}'::jsonb, '{"en": "Logo, typography, brandbook", "fr": "Logo, typographie, brandbook", "es": "Logo, tipografía, brandbook", "de": "Logo, Typografie, Brandbook"}'::jsonb, '{"en": "An identity people recognise at a glance.", "fr": "Une identité que l''on reconnaît au premier regard.", "es": "Una identidad que se reconoce a primera vista.", "de": "Eine Identität, die man auf den ersten Blick erkennt."}'::jsonb, '{"en": "From the logo to the tone of voice, we build a brand that *holds together* on every screen, print and post.", "fr": "Du logo au ton éditorial, nous construisons une marque *cohérente* sur chaque écran, chaque support imprimé et chaque publication.", "es": "Del logotipo al tono de voz, construimos una marca *coherente* en cada pantalla, impreso y publicación.", "de": "Vom Logo bis zur Tonalität bauen wir eine Marke, die auf jedem Bildschirm, in jedem Druck und in jedem Post *zusammenhält*."}'::jsonb, '{"en": ["Visual identity: logo, typography, palette", "Art direction", "Editorial tone of voice", "Brandbook and usage guidelines", "Social media identity", "Rebranding and redesign"], "fr": ["Identité visuelle : logo, typographie, palette", "Direction artistique", "Ton éditorial", "Brandbook et charte d''utilisation", "Identité réseaux sociaux", "Refonte de marque et redesign"], "es": ["Identidad visual: logotipo, tipografía, paleta", "Dirección de arte", "Tono de voz editorial", "Brandbook y guía de uso", "Identidad en redes sociales", "Rebranding y rediseño"], "de": ["Visuelle Identität: Logo, Typografie, Farbpalette", "Art Direction", "Redaktionelle Tonalität", "Brandbook und Nutzungsrichtlinien", "Social-Media-Identität", "Rebranding und Redesign"]}'::jsonb, ARRAY['camille']::text[], CURRENT_TIMESTAMP),
('design', 2, '/images/projects/Benky_0.webp', '{"en": "Product design", "fr": "Design produit", "es": "Diseño de producto", "de": "Produktdesign"}'::jsonb, '{"en": "3–6 weeks", "fr": "3 à 6 semaines", "es": "3 a 6 semanas", "de": "3–6 Wochen"}'::jsonb, '{"en": "UI/UX, prototypes, motion", "fr": "UI/UX, prototypes, motion", "es": "UI/UX, prototipos, motion", "de": "UI/UX, Prototypen, Motion"}'::jsonb, '{"en": "Interfaces that feel obvious the first time.", "fr": "Des interfaces évidentes dès la première fois.", "es": "Interfaces que resultan obvias desde el primer uso.", "de": "Interfaces, die sich vom ersten Klick an selbstverständlich anfühlen."}'::jsonb, '{"en": "We design the journeys and screens of your site or app, *test them with real users* and hand over a system your team can grow.", "fr": "Nous concevons les parcours et les écrans de votre site ou application, *les testons avec de vrais utilisateurs* et livrons un système que votre équipe peut faire évoluer.", "es": "Diseñamos los recorridos y las pantallas de tu web o app, *los probamos con usuarios reales* y entregamos un sistema que tu equipo puede hacer crecer.", "de": "Wir gestalten die Abläufe und Screens Ihrer Website oder App, *testen sie mit echten Nutzern* und übergeben ein System, das Ihr Team weiterentwickeln kann."}'::jsonb, '{"en": ["UI/UX design", "User journeys and wireframes", "Interactive prototypes", "Design systems", "Accessibility from the first mockup", "User testing", "Motion design and animation", "3D and WebGL experiences"], "fr": ["Design UI/UX", "Parcours utilisateurs et wireframes", "Prototypes interactifs", "Design systems", "Accessibilité dès la première maquette", "Tests utilisateurs", "Motion design et animation", "Expériences 3D et WebGL"], "es": ["Diseño UI/UX", "Recorridos de usuario y wireframes", "Prototipos interactivos", "Sistemas de diseño", "Accesibilidad desde la primera maqueta", "Pruebas con usuarios", "Motion design y animación", "Experiencias 3D y WebGL"], "de": ["UI/UX-Design", "User Journeys und Wireframes", "Interaktive Prototypen", "Designsysteme", "Barrierefreiheit ab dem ersten Entwurf", "Nutzertests", "Motion Design und Animation", "3D- und WebGL-Erlebnisse"]}'::jsonb, ARRAY['camille', 'noah']::text[], CURRENT_TIMESTAMP),
('development', 3, '/images/projects/Marcel_2x2_dev.webp', '{"en": "Development", "fr": "Développement", "es": "Desarrollo", "de": "Entwicklung"}'::jsonb, '{"en": "4–12 weeks", "fr": "4 à 12 semaines", "es": "4 a 12 semanas", "de": "4–12 Wochen"}'::jsonb, '{"en": "Web, mobile, back-office", "fr": "Web, mobile, back-office", "es": "Web, móvil, back-office", "de": "Web, Mobile, Backoffice"}'::jsonb, '{"en": "Fast, solid products built to last.", "fr": "Des produits rapides et solides, faits pour durer.", "es": "Productos rápidos y sólidos, hechos para durar.", "de": "Schnelle, solide Produkte, die bleiben."}'::jsonb, '{"en": "We build what we design, from a showcase site to a full business application, with a back-office so you *edit your content yourself*.", "fr": "Nous développons ce que nous concevons, du site vitrine à l''application métier complète, avec un back-office pour *modifier vos contenus vous-même*.", "es": "Desarrollamos lo que diseñamos, de la web corporativa a la aplicación de negocio completa, con un backoffice para que *edites tus contenidos*.", "de": "Wir entwickeln, was wir gestalten, von der Präsentationswebsite bis zur kompletten Business-App, mit einem Backoffice, in dem Sie *Ihre Inhalte selbst pflegen*."}'::jsonb, '{"en": ["Showcase websites and e-commerce", "Web applications", "Mobile apps", "Desktop apps", "Custom back-office to edit your content", "SEO, performance and multilingual"], "fr": ["Sites vitrines et e-commerce", "Applications web", "Applications mobiles", "Applications desktop", "Back-office sur mesure pour vos contenus", "SEO, performance et multilingue"], "es": ["Webs corporativas y e-commerce", "Aplicaciones web", "Apps móviles", "Aplicaciones de escritorio", "Backoffice a medida para tus contenidos", "SEO, rendimiento y multilingüe"], "de": ["Präsentationswebsites und E-Commerce", "Webanwendungen", "Mobile Apps", "Desktop-Apps", "Individuelles Backoffice für Ihre Inhalte", "SEO, Performance und Mehrsprachigkeit"]}'::jsonb, ARRAY['noah', 'fanga', 'mazouz']::text[], CURRENT_TIMESTAMP),
('content', 4, '/videos/LauraHerve_web.mp4', '{"en": "Content", "fr": "Contenus", "es": "Contenidos", "de": "Inhalte"}'::jsonb, '{"en": "1–3 weeks", "fr": "1 à 3 semaines", "es": "1 a 3 semanas", "de": "1–3 Wochen"}'::jsonb, '{"en": "Photo, video, social", "fr": "Photo, vidéo, réseaux", "es": "Foto, vídeo, redes", "de": "Foto, Video, Social"}'::jsonb, '{"en": "Images and movement that make people stop scrolling.", "fr": "Des images et du mouvement qui arrêtent le scroll.", "es": "Imágenes y movimiento que detienen el scroll.", "de": "Bilder und Bewegung, bei denen man aufhört zu scrollen."}'::jsonb, '{"en": "We photograph, film and write the content that *gives your brand its rhythm*, on your site and on social media.", "fr": "Nous photographions, filmons et écrivons les contenus qui *donnent du rythme à votre marque*, sur votre site comme sur les réseaux.", "es": "Fotografiamos, grabamos y escribimos los contenidos que *dan ritmo a tu marca*, en tu web y en las redes.", "de": "Wir fotografieren, filmen und schreiben die Inhalte, die *Ihrer Marke Rhythmus geben*, auf Ihrer Website wie in den sozialen Netzwerken."}'::jsonb, '{"en": ["Photography", "Video", "Social media content"], "fr": ["Photographie", "Vidéo", "Contenus pour les réseaux sociaux"], "es": ["Fotografía", "Vídeo", "Contenido para redes sociales"], "de": ["Fotografie", "Video", "Social-Media-Content"]}'::jsonb, ARRAY['camille']::text[], CURRENT_TIMESTAMP),
('care', 5, '/images/projects/HandVision_3.webp', '{"en": "Hosting & care", "fr": "Hébergement & suivi", "es": "Alojamiento y soporte", "de": "Hosting & Betreuung"}'::jsonb, '{"en": "Ongoing", "fr": "En continu", "es": "Continuo", "de": "Laufend"}'::jsonb, '{"en": "Hosting, maintenance, training", "fr": "Hébergement, maintenance, formation", "es": "Alojamiento, mantenimiento, formación", "de": "Hosting, Wartung, Schulung"}'::jsonb, '{"en": "We stay after launch day.", "fr": "Nous restons après le lancement.", "es": "Nos quedamos después del lanzamiento.", "de": "Wir bleiben auch nach dem Launch."}'::jsonb, '{"en": "We host what we build *on our own servers*, keep it up to date and give your team the tools of the Facile Suite to work better every day.", "fr": "Nous hébergeons ce que nous construisons *sur nos propres serveurs*, le maintenons à jour et donnons à votre équipe les outils de la Suite Facile pour mieux travailler au quotidien.", "es": "Alojamos lo que construimos *en nuestros propios servidores*, lo mantenemos al día y damos a tu equipo las herramientas de la Suite Facile para trabajar mejor cada día.", "de": "Wir hosten, was wir bauen, *auf eigenen Servern*, halten es aktuell und geben Ihrem Team die Tools der Facile Suite für einen besseren Arbeitsalltag."}'::jsonb, '{"en": ["Hosting on our own servers", "Monitoring and backups", "Maintenance and updates", "Business tools from the Facile Suite", "Digital transformation of your workflows", "Team training"], "fr": ["Hébergement sur nos propres serveurs", "Supervision et sauvegardes", "Maintenance et mises à jour", "Outils métier de la Suite Facile", "Transformation numérique de vos processus", "Formation de vos équipes"], "es": ["Alojamiento en nuestros propios servidores", "Monitorización y copias de seguridad", "Mantenimiento y actualizaciones", "Herramientas de negocio de la Suite Facile", "Transformación digital de tus procesos", "Formación de tus equipos"], "de": ["Hosting auf eigenen Servern", "Monitoring und Backups", "Wartung und Updates", "Business-Tools aus der Facile Suite", "Digitale Transformation Ihrer Abläufe", "Schulung Ihres Teams"]}'::jsonb, ARRAY['fanga', 'mazouz']::text[], CURRENT_TIMESTAMP);
